CREATE DATABASE IF NOT EXISTS rent_guardian CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE rent_guardian;
CREATE TABLE roles (id SMALLINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, name VARCHAR(32) NOT NULL UNIQUE);
CREATE TABLE users (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, public_id CHAR(20) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, phone VARCHAR(24), deleted_at DATETIME, password_hash VARCHAR(255) NOT NULL, status ENUM('active','suspended') NOT NULL DEFAULT 'active', verified_at DATETIME, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE user_roles (user_id BIGINT UNSIGNED NOT NULL, role_id SMALLINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE locations (id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT, parent_id INT UNSIGNED, kind ENUM('division','district','area','sub_area') NOT NULL, name VARCHAR(100) NOT NULL, latitude DECIMAL(10,7), longitude DECIMAL(10,7), FOREIGN KEY(parent_id) REFERENCES locations(id), UNIQUE(parent_id,name));
CREATE TABLE addresses (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, location_id INT UNSIGNED NOT NULL, road_no VARCHAR(60) NOT NULL, house_no VARCHAR(60) NOT NULL, house_name VARCHAR(150), floor_no SMALLINT NOT NULL, flat_no VARCHAR(40) NOT NULL, latitude DECIMAL(10,7), longitude DECIMAL(10,7), FOREIGN KEY(location_id) REFERENCES locations(id));
CREATE TABLE bank_accounts (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, bank_name VARCHAR(100) NOT NULL, account_name VARCHAR(120) NOT NULL, account_number VARCHAR(40) NOT NULL, routing_code VARCHAR(40) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS listing_drafts (user_id BIGINT UNSIGNED PRIMARY KEY, payload LONGTEXT NOT NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE properties (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, owner_id BIGINT UNSIGNED NOT NULL, address_id BIGINT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, description TEXT, kind ENUM('apartment','room','house') NOT NULL DEFAULT 'apartment', bedrooms TINYINT UNSIGNED NOT NULL, bathrooms TINYINT UNSIGNED NOT NULL, balconies TINYINT UNSIGNED NOT NULL DEFAULT 0, size_sqft INT UNSIGNED NOT NULL, garage BOOLEAN NOT NULL DEFAULT 0, rent DECIMAL(12,2) NOT NULL CHECK(rent>0), utility_charge DECIMAL(12,2) NOT NULL DEFAULT 0 CHECK(utility_charge>=0), advance_months TINYINT UNSIGNED NOT NULL DEFAULT 2, tenant_preference ENUM('family','bachelor','any') NOT NULL DEFAULT 'any', available_from DATE NOT NULL, house_rules TEXT, gate_closes TIME, lift_closes TIME, status ENUM('draft','pending','published','paused','rented','removed') NOT NULL DEFAULT 'pending', tour_url VARCHAR(500), approved_by BIGINT UNSIGNED, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(owner_id) REFERENCES users(id), FOREIGN KEY(address_id) REFERENCES addresses(id), FOREIGN KEY(approved_by) REFERENCES users(id), INDEX property_search(status,rent,bedrooms,available_from));
CREATE TABLE utility_types (id SMALLINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) UNIQUE NOT NULL);
CREATE TABLE property_utilities (property_id BIGINT UNSIGNED NOT NULL, utility_type_id SMALLINT UNSIGNED NOT NULL, included BOOLEAN NOT NULL DEFAULT 1, amount DECIMAL(12,2) NOT NULL DEFAULT 0 CHECK(amount>=0), PRIMARY KEY(property_id,utility_type_id), FOREIGN KEY(property_id) REFERENCES properties(id), FOREIGN KEY(utility_type_id) REFERENCES utility_types(id));
CREATE TABLE property_photos (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, property_id BIGINT UNSIGNED NOT NULL, path VARCHAR(500) NOT NULL, caption VARCHAR(150), sort_order INT NOT NULL DEFAULT 0, category VARCHAR(40) NOT NULL DEFAULT 'Other', deleted_at DATETIME NULL, INDEX photo_order(property_id,deleted_at,sort_order,id), FOREIGN KEY(property_id) REFERENCES properties(id));
CREATE TABLE saved_properties (user_id BIGINT UNSIGNED NOT NULL, property_id BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,property_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(property_id) REFERENCES properties(id));
CREATE TABLE provider_profiles (user_id BIGINT UNSIGNED PRIMARY KEY, business_name VARCHAR(150) NOT NULL, location_id INT UNSIGNED NOT NULL, latitude DECIMAL(10,7), longitude DECIMAL(10,7), radius_km DECIMAL(4,1) NOT NULL DEFAULT 4, available BOOLEAN NOT NULL DEFAULT 1, bio TEXT, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(location_id) REFERENCES locations(id));
CREATE TABLE service_categories (id SMALLINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL UNIQUE, kind ENUM('maintenance','installation','grocery','catering','maid','moving') NOT NULL);
CREATE TABLE provider_categories (provider_id BIGINT UNSIGNED NOT NULL, category_id SMALLINT UNSIGNED NOT NULL, PRIMARY KEY(provider_id,category_id), FOREIGN KEY(provider_id) REFERENCES provider_profiles(user_id), FOREIGN KEY(category_id) REFERENCES service_categories(id));
CREATE TABLE appointments (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, property_id BIGINT UNSIGNED NOT NULL, requested_by BIGINT UNSIGNED NOT NULL, assigned_to BIGINT UNSIGNED, kind ENUM('viewing','inspection','move_out','meeting','installation') NOT NULL, starts_at DATETIME NOT NULL, status ENUM('requested','confirmed','completed','cancelled') NOT NULL DEFAULT 'requested', otp_hash VARCHAR(255), otp_attempts TINYINT UNSIGNED NOT NULL DEFAULT 0, otp_expires_at DATETIME, otp_verified_at DATETIME, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(property_id) REFERENCES properties(id), FOREIGN KEY(requested_by) REFERENCES users(id), FOREIGN KEY(assigned_to) REFERENCES users(id), INDEX appointment_calendar(assigned_to,starts_at));
CREATE TABLE property_visits (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, property_id BIGINT UNSIGNED NOT NULL, appointment_id BIGINT UNSIGNED NOT NULL UNIQUE, visited_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(property_id) REFERENCES properties(id), FOREIGN KEY(appointment_id) REFERENCES appointments(id));
CREATE TABLE inspections (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, property_id BIGINT UNSIGNED NOT NULL, agent_id BIGINT UNSIGNED NOT NULL, appointment_id BIGINT UNSIGNED, kind ENUM('move_in','move_out') NOT NULL DEFAULT 'move_in', status ENUM('draft','submitted','approved','rejected') NOT NULL DEFAULT 'submitted', summary TEXT NOT NULL, approved_by BIGINT UNSIGNED, inspected_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(property_id) REFERENCES properties(id), FOREIGN KEY(agent_id) REFERENCES users(id), FOREIGN KEY(appointment_id) REFERENCES appointments(id), FOREIGN KEY(approved_by) REFERENCES users(id));
CREATE TABLE inspection_rooms (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, inspection_id BIGINT UNSIGNED NOT NULL, name VARCHAR(100) NOT NULL, room_type VARCHAR(40) NOT NULL, size_sqft DECIMAL(8,2), electric_ports SMALLINT UNSIGNED DEFAULT 0, light_holders SMALLINT UNSIGNED DEFAULT 0, balcony BOOLEAN DEFAULT 0, cabinet BOOLEAN DEFAULT 0, curtain_stand BOOLEAN DEFAULT 0, bedside_ports BOOLEAN DEFAULT 0, worktable_ports BOOLEAN DEFAULT 0, gas_connection VARCHAR(40), notes TEXT, FOREIGN KEY(inspection_id) REFERENCES inspections(id));
CREATE TABLE inspection_items (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, room_id BIGINT UNSIGNED NOT NULL, component VARCHAR(100) NOT NULL, condition_status ENUM('working','broken','cracked','jammed','missing','not_applicable') NOT NULL, permanent_damage BOOLEAN NOT NULL DEFAULT 0, description TEXT, photo_document_id BIGINT UNSIGNED, estimate DECIMAL(12,2) NOT NULL DEFAULT 0, repair_decision ENUM('pending','owner','guardian','declined','fixed') NOT NULL DEFAULT 'pending', FOREIGN KEY(room_id) REFERENCES inspection_rooms(id));
CREATE TABLE tenancies (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, property_id BIGINT UNSIGNED NOT NULL, head_tenant_id BIGINT UNSIGNED NOT NULL, start_date DATE NOT NULL, end_date DATE, move_out_date DATE, rent DECIMAL(12,2) NOT NULL CHECK(rent>0), utility_charge DECIMAL(12,2) NOT NULL DEFAULT 0, advance_paid DECIMAL(12,2) NOT NULL DEFAULT 0, status ENUM('pending_verification','ready','active','notice','ended') NOT NULL DEFAULT 'pending_verification', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(property_id) REFERENCES properties(id), FOREIGN KEY(head_tenant_id) REFERENCES users(id), INDEX tenancy_property(property_id,status));
CREATE TABLE tenancy_members (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, tenancy_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED, name VARCHAR(120) NOT NULL, relationship VARCHAR(60), phone VARCHAR(24), national_id VARCHAR(60), FOREIGN KEY(tenancy_id) REFERENCES tenancies(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE documents (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, tenancy_id BIGINT UNSIGNED, property_id BIGINT UNSIGNED, kind ENUM('police_verification','identity','receipt','inspection_photo','property_photo','maintenance_evidence') NOT NULL, original_name VARCHAR(255) NOT NULL, storage_path VARCHAR(255) NOT NULL UNIQUE, mime_type VARCHAR(100) NOT NULL, size_bytes INT UNSIGNED NOT NULL, status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', reviewed_by BIGINT UNSIGNED, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(tenancy_id) REFERENCES tenancies(id), FOREIGN KEY(property_id) REFERENCES properties(id), FOREIGN KEY(reviewed_by) REFERENCES users(id));
ALTER TABLE inspection_items ADD FOREIGN KEY(photo_document_id) REFERENCES documents(id);
CREATE TABLE contracts (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, tenancy_id BIGINT UNSIGNED NOT NULL UNIQUE, body LONGTEXT NOT NULL, version INT UNSIGNED NOT NULL DEFAULT 1, content_hash CHAR(64) NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(tenancy_id) REFERENCES tenancies(id));
CREATE TABLE contract_signatures (contract_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, signer_role ENUM('owner','tenant') NOT NULL, signed_name VARCHAR(120) NOT NULL, signed_at DATETIME DEFAULT CURRENT_TIMESTAMP, ip_address VARCHAR(45), content_hash CHAR(64) NOT NULL, PRIMARY KEY(contract_id,signer_role), FOREIGN KEY(contract_id) REFERENCES contracts(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE maintenance_requests (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, tenancy_id BIGINT UNSIGNED NOT NULL, category_id SMALLINT UNSIGNED NOT NULL, requested_by BIGINT UNSIGNED NOT NULL, provider_id BIGINT UNSIGNED, preferred_provider_id BIGINT UNSIGNED, title VARCHAR(180) NOT NULL, description TEXT NOT NULL, urgency ENUM('scheduled','instant') NOT NULL DEFAULT 'scheduled', appointment_at DATETIME, owner_involved BOOLEAN NOT NULL DEFAULT 1, owner_decision ENUM('pending','approved','declined','not_needed') NOT NULL DEFAULT 'pending', pay_later BOOLEAN NOT NULL DEFAULT 0, status ENUM('open','approved','assigned','in_progress','completed','cancelled') NOT NULL DEFAULT 'open', otp_hash VARCHAR(255), otp_attempts TINYINT UNSIGNED NOT NULL DEFAULT 0, otp_expires_at DATETIME, otp_verified_at DATETIME, tenant_cost DECIMAL(12,2), owner_cost DECIMAL(12,2), provider_cost DECIMAL(12,2), approved_by BIGINT UNSIGNED, cost_confirmed_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(tenancy_id) REFERENCES tenancies(id), FOREIGN KEY(category_id) REFERENCES service_categories(id), FOREIGN KEY(requested_by) REFERENCES users(id), FOREIGN KEY(provider_id) REFERENCES provider_profiles(user_id), FOREIGN KEY(preferred_provider_id) REFERENCES provider_profiles(user_id), FOREIGN KEY(approved_by) REFERENCES users(id), INDEX job_status(status,urgency,provider_id));
CREATE TABLE request_events (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, request_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, status VARCHAR(40) NOT NULL, message TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(request_id) REFERENCES maintenance_requests(id), FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE catalog_products (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, provider_id BIGINT UNSIGNED NOT NULL, category_id SMALLINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, description TEXT, unit VARCHAR(40) NOT NULL, price DECIMAL(12,2) NOT NULL CHECK(price>=0), installation_cost DECIMAL(12,2) NOT NULL DEFAULT 0 CHECK(installation_cost>=0), recurring_cost DECIMAL(12,2) NOT NULL DEFAULT 0 CHECK(recurring_cost>=0), active BOOLEAN NOT NULL DEFAULT 1, FOREIGN KEY(provider_id) REFERENCES provider_profiles(user_id), FOREIGN KEY(category_id) REFERENCES service_categories(id));
CREATE TABLE orders (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, tenancy_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, provider_id BIGINT UNSIGNED NOT NULL, address_id BIGINT UNSIGNED NOT NULL, kind ENUM('grocery','installation','moving','maid') NOT NULL, status ENUM('placed','accepted','delivering','completed','cancelled') NOT NULL DEFAULT 'placed', pay_later BOOLEAN NOT NULL DEFAULT 0, scheduled_at DATETIME, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(tenancy_id) REFERENCES tenancies(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(provider_id) REFERENCES provider_profiles(user_id), FOREIGN KEY(address_id) REFERENCES addresses(id));
CREATE TABLE order_items (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, order_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, quantity DECIMAL(8,2) NOT NULL CHECK(quantity>0), unit_price DECIMAL(12,2) NOT NULL, installation_cost DECIMAL(12,2) NOT NULL DEFAULT 0, customization TEXT, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(product_id) REFERENCES catalog_products(id));
CREATE TABLE meal_plans (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, provider_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, meal ENUM('breakfast','lunch','dinner') NOT NULL, description TEXT, price_per_person DECIMAL(12,2) NOT NULL CHECK(price_per_person>0), active BOOLEAN DEFAULT 1, FOREIGN KEY(provider_id) REFERENCES provider_profiles(user_id));
CREATE TABLE meal_subscriptions (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, tenancy_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, meal_plan_id BIGINT UNSIGNED NOT NULL, people SMALLINT UNSIGNED NOT NULL CHECK(people>0), starts_on DATE NOT NULL, ends_on DATE NOT NULL, pay_later BOOLEAN NOT NULL DEFAULT 0, status ENUM('active','cancelled','ended') DEFAULT 'active', FOREIGN KEY(tenancy_id) REFERENCES tenancies(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(meal_plan_id) REFERENCES meal_plans(id), CHECK(ends_on>=starts_on));
CREATE TABLE invoices (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, tenancy_id BIGINT UNSIGNED, period DATE NOT NULL, due_date DATE NOT NULL, status ENUM('open','paid','void') NOT NULL DEFAULT 'open', billing_group VARCHAR(80) NOT NULL DEFAULT 'monthly', UNIQUE tenancy_period_group(tenancy_id,period,user_id,billing_group), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(tenancy_id) REFERENCES tenancies(id));
CREATE TABLE invoice_items (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, invoice_id BIGINT UNSIGNED NOT NULL, kind ENUM('rent','utility','maintenance','grocery','catering','installation','advance','moving','maid','discount') NOT NULL, description VARCHAR(255) NOT NULL, amount DECIMAL(12,2) NOT NULL, request_id BIGINT UNSIGNED UNIQUE, order_id BIGINT UNSIGNED UNIQUE, subscription_id BIGINT UNSIGNED, FOREIGN KEY(invoice_id) REFERENCES invoices(id), FOREIGN KEY(request_id) REFERENCES maintenance_requests(id), FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(subscription_id) REFERENCES meal_subscriptions(id));
CREATE TABLE payments (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, invoice_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(12,2) NOT NULL CHECK(amount>0), method ENUM('bank_transfer','bkash','cash') NOT NULL, channel ENUM('app','call','bank_transfer') NOT NULL DEFAULT 'app', reference VARCHAR(150) NOT NULL, receipt_document_id BIGINT UNSIGNED, status ENUM('submitted','reviewed','confirmed','rejected') DEFAULT 'submitted', reviewed_by BIGINT UNSIGNED, confirmed_by BIGINT UNSIGNED, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, confirmed_at DATETIME, FOREIGN KEY(invoice_id) REFERENCES invoices(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(receipt_document_id) REFERENCES documents(id), FOREIGN KEY(reviewed_by) REFERENCES users(id), FOREIGN KEY(confirmed_by) REFERENCES users(id), UNIQUE(method,reference));
CREATE TABLE reviews (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, author_id BIGINT UNSIGNED NOT NULL, subject_id BIGINT UNSIGNED NOT NULL, tenancy_id BIGINT UNSIGNED NOT NULL, request_id BIGINT UNSIGNED, order_id BIGINT UNSIGNED, rating TINYINT UNSIGNED NOT NULL CHECK(rating BETWEEN 1 AND 5), comment TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(author_id) REFERENCES users(id), FOREIGN KEY(subject_id) REFERENCES users(id), FOREIGN KEY(tenancy_id) REFERENCES tenancies(id), FOREIGN KEY(request_id) REFERENCES maintenance_requests(id), FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE support_tickets (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, property_id BIGINT UNSIGNED, assigned_to BIGINT UNSIGNED, category ENUM('listing','inspection','maintenance','technical','callback','payment','complaint') NOT NULL, subject VARCHAR(180) NOT NULL, message TEXT NOT NULL, contact_channel ENUM('app','call') DEFAULT 'app', status ENUM('open','in_progress','resolved','closed') DEFAULT 'open', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(property_id) REFERENCES properties(id), FOREIGN KEY(assigned_to) REFERENCES users(id));
CREATE TABLE complaints (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, tenancy_id BIGINT UNSIGNED NOT NULL, filed_by BIGINT UNSIGNED NOT NULL, about_user BIGINT UNSIGNED NOT NULL, description TEXT NOT NULL, status ENUM('open','reviewing','resolved') DEFAULT 'open', resolution TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(tenancy_id) REFERENCES tenancies(id), FOREIGN KEY(filed_by) REFERENCES users(id), FOREIGN KEY(about_user) REFERENCES users(id));
CREATE TABLE notifications (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, message TEXT NOT NULL, link VARCHAR(180), read_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE notification_preferences (user_id BIGINT UNSIGNED PRIMARY KEY, location_id INT UNSIGNED, new_listings BOOLEAN DEFAULT 1, monthly_checkin BOOLEAN DEFAULT 1, appointment_reminders BOOLEAN DEFAULT 1, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(location_id) REFERENCES locations(id));
CREATE TABLE reward_ledger (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, request_id BIGINT UNSIGNED UNIQUE, points INT NOT NULL, reason VARCHAR(180) NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(request_id) REFERENCES maintenance_requests(id));
CREATE TABLE referrals (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, referrer_id BIGINT UNSIGNED NOT NULL, referred_email VARCHAR(190) NOT NULL UNIQUE, referred_user_id BIGINT UNSIGNED UNIQUE, status ENUM('invited','registered','rewarded') DEFAULT 'invited', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(referrer_id) REFERENCES users(id), FOREIGN KEY(referred_user_id) REFERENCES users(id));
CREATE TABLE tenancy_transfers (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, tenancy_id BIGINT UNSIGNED NOT NULL, from_user_id BIGINT UNSIGNED NOT NULL, to_user_id BIGINT UNSIGNED NOT NULL, status ENUM('requested','accepted','approved','rejected') NOT NULL DEFAULT 'requested', approved_by BIGINT UNSIGNED, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(tenancy_id) REFERENCES tenancies(id), FOREIGN KEY(from_user_id) REFERENCES users(id), FOREIGN KEY(to_user_id) REFERENCES users(id), FOREIGN KEY(approved_by) REFERENCES users(id));
CREATE TABLE campaigns (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, name VARCHAR(150) NOT NULL, location_id INT UNSIGNED NOT NULL, starts_on DATE NOT NULL, ends_on DATE NOT NULL, FOREIGN KEY(location_id) REFERENCES locations(id));
CREATE TABLE campaign_assignments (campaign_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(campaign_id,user_id), FOREIGN KEY(campaign_id) REFERENCES campaigns(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE campaign_checklists (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, campaign_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, completed_on DATE NOT NULL, owner_name VARCHAR(120), owner_phone VARCHAR(24), checklist TEXT NOT NULL, FOREIGN KEY(campaign_id) REFERENCES campaigns(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE training_materials (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, title VARCHAR(180) NOT NULL, body TEXT NOT NULL, audience VARCHAR(40) NOT NULL);
CREATE TABLE audit_logs (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, actor_id BIGINT UNSIGNED, action VARCHAR(80) NOT NULL, entity VARCHAR(80) NOT NULL, entity_id BIGINT UNSIGNED, before_data LONGTEXT, after_data LONGTEXT, ip_address VARCHAR(45), created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_id) REFERENCES users(id), INDEX audit_entity(entity,entity_id,created_at));
CREATE TABLE auth_attempts (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, identity_hash CHAR(64) NOT NULL, ip_address VARCHAR(45) NOT NULL, attempted_at DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX attempt_window(ip_address,attempted_at));
CREATE TABLE job_runs (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, job_key VARCHAR(180) NOT NULL UNIQUE, ran_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE system_settings (setting_key VARCHAR(80) PRIMARY KEY, setting_value TEXT NOT NULL, updated_by BIGINT UNSIGNED, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(updated_by) REFERENCES users(id));
CREATE TABLE user_stories (id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT, persona VARCHAR(80) NOT NULL, want_to TEXT NOT NULL, benefit TEXT, module VARCHAR(60) NOT NULL, related_tables VARCHAR(500) NOT NULL, implementation_status ENUM('COMPLETED','PARTIALLY COMPLETED','BLOCKED','FAILED','WAITING FOR INPUT') NOT NULL DEFAULT 'PARTIALLY COMPLETED');
CREATE OR REPLACE VIEW v_invoice_balances AS SELECT i.*, COALESCE((SELECT SUM(ii.amount) FROM invoice_items ii WHERE ii.invoice_id=i.id),0) total, COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.invoice_id=i.id AND p.status='confirmed'),0) paid, COALESCE((SELECT SUM(ii.amount) FROM invoice_items ii WHERE ii.invoice_id=i.id),0)-COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.invoice_id=i.id AND p.status='confirmed'),0) balance FROM invoices i;
CREATE OR REPLACE VIEW v_property_locations AS SELECT p.*,a.road_no,a.house_no,a.house_name,a.floor_no,a.flat_no,a.latitude,a.longitude,l.name sub_area,area.name area,district.name district,division.name division FROM properties p JOIN addresses a ON a.id=p.address_id JOIN locations l ON l.id=a.location_id JOIN locations area ON area.id=l.parent_id JOIN locations district ON district.id=area.parent_id JOIN locations division ON division.id=district.parent_id;
CREATE OR REPLACE VIEW v_cost_reconciliation AS SELECT m.id request_id,m.tenancy_id,m.tenant_cost,m.owner_cost,m.provider_cost,CASE WHEN m.provider_cost IS NULL THEN 'awaiting_provider' WHEN COALESCE(m.owner_cost,m.tenant_cost) IS NULL THEN 'awaiting_customer' WHEN ABS(m.provider_cost-COALESCE(m.owner_cost,m.tenant_cost))<=0.01 THEN 'matched' ELSE 'mismatch' END reconciliation FROM maintenance_requests m;
